# 8-connected bg from border
vis8=set();q=deque()
for r in range(H):
 for c in (0,W-1):
  if g[r][c]==2:q.append((r,c))
for c in range(W):
 for r in (0,H-1):
  if g[r][c]==2:q.append((r,c))
while q:
 x=q.popleft()
 if x in vis8:continue
 r,c=x
 if not(0<=r<H and 0<=c<W) or g[r][c]!=2:continue
 vis8.add(x)
 for dr in (-1,0,1):
  for dc in (-1,0,1):
   if dr or dc:q.append((r+dr,c+dc))
[(r,c) for r in range(H) for c in range(W) if g[r][c]==2 and (r,c) not in vis8][:50]

# components of 2 within grid, no outside edges; report component sizes and extents, contains corners
seen=set(); comps=[]
for r in range(H):
 for c in range(W):
  if g[r][c]!=2 or (r,c) in seen:continue
  q=deque([(r,c)]);seen.add((r,c)); comp=[]
  while q:
   x=q.popleft();comp.append(x);rr,cc=x
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    y=(rr+dr,cc+dc)
    if 0<=y[0]<H and 0<=y[1]<W and g[y[0]][y[1]]==2 and y not in seen:seen.add(y);q.append(y)
  comps.append(comp)
[(len(c), (min(r for r,x in c),max(r for r,x in c),min(x for r,x in c),max(x for r,x in c)),[(r,x) for r,x in c if r in (0,H-1) or x in (0,W-1)][:5]) for c in comps]
